88	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
89	        LocalDate today = sheet.getToday();
90	        Person person = people.findByIdAndSheetId(personId, sheetId)
91	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
92	        refuseIfClosed(sheetId, date != null ? date : today);
93	        refuseIfRetired(person, date != null ? date : today);
