150	    @Transactional
151	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
152	        sheets.load(sheetId, user);
153	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
154	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
155	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
156	        refuseIfClosed(sheetId, claim.getDate());
157	        if (!claim.getStatus().canBecome(next)) {
158	            throw new ResponseStatusException(HttpStatus.CONFLICT,
159	                    "A " + claim.getStatus() + " claim cannot become " + next);
160	        }
161	        String action = switch (next) {
162	            case OPEN -> "open";
163	            case SETTLED -> "settle";
164	            case VOID -> "void";
165	            default -> null;
166	        };
167	        if (action != null && !sheet.allows(action, roles.roleOf(sheetId, user))) {
168	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
169	        }
170	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
171	            throw new ResponseStatusException(HttpStatus.CONFLICT,
172	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
173	        }
174	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
175	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
