260	    /** A steward approves a PENDING claim: it becomes SETTLED, its due fixed as it is at this moment (its live
261	     *  figure with the late charge it has gained). Refused for a clerk, for the user who opened the claim, for a
262	     *  claim that is not PENDING and for one dated inside a closed period. */
263	    @Transactional
264	    public Claim approve(String sheetId, String user, long id) {
265	        sheets.load(sheetId, user);
266	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
267	        Claim claim = pendingClaim(sheetId, user, id);
268	        if (user.equals(claim.getOpenedBy())) {
