286	     *  statement if that statement included it. Refused for a clerk, for a claim that is not PENDING and for one
287	     *  dated inside a closed period. */
288	    @Transactional
289	    public Claim reject(String sheetId, String user, long id, String reason) {
290	        sheets.load(sheetId, user);
291	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
292	        Claim claim = pendingClaim(sheetId, user, id);
293	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
294	        Rollup.Figures before = rollup.of(sheetId);
295	        claim.setStatus(ClaimStatus.OPEN);
296	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
297	        Claim changed = claims.saveAndFlush(claim);
298	        audit.recordOnCommit(entry("CLAIM_REJECTED", user, person, changed, changed.getNumber())
299	                + " reason=" + reason.trim());
300	        rollup.recordChanges(sheetId, user, before);
301	        return changed;
302	    }
