304	    /** A steward re-settles a SETTLED claim: its due is fixed again at the figure it would have today as an open
305	     *  claim bound by no statement (its live figure at today's rates, grades and floor, with the late charge it
306	     *  would have gained by today on top), and its status log gains a SETTLED line. Refused for a clerk, for a
307	     *  claim that is not SETTLED and for one dated inside a closed period. */
308	    @Transactional
309	    public Claim resettle(String sheetId, String user, long id) {
310	        sheets.load(sheetId, user);
311	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
312	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
313	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
314	        refuseIfClosed(sheetId, claim.getDate());
315	        if (claim.getStatus() != ClaimStatus.SETTLED) {
316	            throw new ResponseStatusException(HttpStatus.CONFLICT,
317	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
318	        }
319	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
320	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim");
321	        }
322	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
323	        BigDecimal live = liveNow(sheet, claim, person);
324	        BigDecimal due = live == null ? null : live.add(lateChargeAsOpen(claim, live, sheet));
325	        Rollup.Figures before = rollup.of(sheetId);
326	        String old = dueText(claim);
327	        claim.setSettledDue(due);
328	        claim.logStatus(user, sheet.getToday(), due);
329	        Claim changed = claims.saveAndFlush(claim);
330	        audit.recordOnCommit(entry("CLAIM_RESETTLED", user, person, changed, changed.getNumber())
331	                + " old=" + old + " new=" + dueText(changed));
332	        rollup.recordChanges(sheetId, user, before);
333	        return changed;
334	    }
335	
336	    /** A user whose role may reassign moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
337	     *  loses any figure a statement bound it to (it is live again until its new person's next statement), and is
338	     *  listed as its new person's newest claim. Refused for a role the permission matrix does not allow (by default a clerk), for a SETTLED or VOID claim, for a move to the
339	     *  person it is already of, for one dated inside a closed period or after the new person retired, and for a
340	     *  correction the new person has no SETTLED claim of that number for. */
341	    @Transactional
342	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
343	        sheets.load(sheetId, user);
344	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
345	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
346	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
347	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
348	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
349	        if (!sheet.allows("reassign", roles.roleOf(sheetId, user))) {
350	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
351	        }
352	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
353	            throw new ResponseStatusException(HttpStatus.CONFLICT,
354	                    "A " + claim.getStatus() + " claim cannot be reassigned");
355	        }
356	        if (claim.getPersonId().equals(to.getId())) {
357	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already " + to.getName() + "'s");
358	        }
359	        refuseIfClosed(sheetId, claim.getDate());
360	        refuseIfRetired(to, claim.getDate());
361	        refuseUnlessCorrects(sheetId, to.getId(), claim.getAmount(), claim.getCorrects());
362	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
363	        Rollup.Figures before = rollup.of(sheetId);
364	        claim.unbind();
365	        claim.reassign(to.getId(), claims.lastListed(sheetId) + 1);
366	        Claim moved = claims.saveAndFlush(claim);
367	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, moved, moved.getNumber())
368	                + " from=" + from.getName() + " to=" + to.getName());
369	        rollup.recordChanges(sheetId, user, before);
370	        return moved;
371	    }
372	
373	    /** The PENDING claim a steward approves or rejects; refused for a clerk, a claim in any other status and one
374	     *  dated inside a closed period. */
375	    private Claim pendingClaim(String sheetId, String user, long id) {
376	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
377	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
378	        refuseIfClosed(sheetId, claim.getDate());
379	        if (claim.getStatus() != ClaimStatus.PENDING) {
380	            throw new ResponseStatusException(HttpStatus.CONFLICT,
381	                    "A " + claim.getStatus() + " claim is not waiting for approval");
382	        }
383	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
384	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim");
385	        }
386	        return claim;
387	    }
388	
389	    /** The due a claim would be settled at now: its bound figure, else its live one, with the late charge it has
390	     *  gained on top; null when it has no figure. */
391	    private BigDecimal dueNow(Sheet sheet, Claim claim, Person person) {
392	        BigDecimal live = liveNow(sheet, claim, person);
393	        // Settling freezes the claim's figure (its bound one, else its live one) with the late charge it has gained.
394	        BigDecimal figure = claim.isBound() ? claim.getBoundDue() : live;
395	        return figure == null ? null : figure.add(lateCharge(claim, figure, sheet));
396	    }
397	
398	    /** A claim's live figure as rates, grades and the floor are now, bound by no statement; null when its grade has
399	     *  no rate in force on its date. */
400	    private BigDecimal liveNow(Sheet sheet, Claim claim, Person person) {
401	        String sheetId = sheet.getId();
402	        return Rate.inForceOn(rates.findBySheetIdAndGrade(sheetId, person.gradeOn(claim.getDate())), claim.getDate())
403	                .map(Rate::getRate)
404	                .map(rate -> liveFigure(claim, rate, sheet.floorOn(claim.getDate()), sheet.roundingFor(roundingDate(claim,
405	                        claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId())))))
406	                .orElse(null);
407	    }
408	
409	    /** The due a claim shows as it is now: the due fixed when it was settled, else the one it would be settled at. */
410	    private BigDecimal shownDue(Sheet sheet, Claim claim, Person person) {
411	        return claim.getSettledDue() != null ? claim.getSettledDue() : dueNow(sheet, claim, person);
412	    }
413	
414	    private static String dueText(Claim claim) {
415	        return claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
416	    }
417	
418	    /** The next number for a claim dated on this day, opened now: within its period (<period name>-<n>, or X-<n>
419	     *  in no period) while the sheet's period numbering is on by its today, else the sheet's next number. */
420	    private String nextNumber(Sheet sheet, LocalDate date) {
421	        if (!sheet.numbersPerPeriod()) {
422	            return String.valueOf(sheet.nextClaimNumber());
423	        }
424	        String prefix = periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
425	                .filter(p -> p.contains(date)).map(Period::getName).findFirst().orElse(NO_PERIOD);
426	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
427	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
428	        String number = sequence.next();
429	        sequences.save(sequence);
430	        return number;
431	    }
432	
433	    /** Refuse to settle or approve a claim with no proofs whose due is above the proof threshold in force on its
434	     *  date (a claim with no due, or on a sheet with no threshold then, needs none). */
435	    private static void refuseUnproven(Sheet sheet, Claim claim, BigDecimal due) {
436	        BigDecimal threshold = sheet.proofThresholdOn(claim.getDate());
437	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
438	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
439	                    "A claim whose due is above the proof threshold of " + threshold + " needs a proof first");
440	        }
441	    }
442	
443	    /** Whether a settle by this user must wait for a steward: they are a clerk and the due is above the sheet's
444	     *  clerk limit (a claim with no due is within any limit). */
445	    private boolean overClerkLimit(Sheet sheet, String user, BigDecimal due) {
446	        BigDecimal limit = sheet.getClerkLimit();
447	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
448	            return false;
449	        }
450	        return !Role.STEWARD.equals(roles.roleOf(sheet.getId(), user));
451	    }
452	
453	    /** Refuse a correction (a negative amount) that does not name, by number, a SETTLED claim of the same person,
454	     *  and a claim that is not a correction but names one. */
455	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
456	        if (amount.signum() >= 0) {
457	            if (corrects != null) {
458	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
459	                        "Only a correction (a negative amount) names a claim it corrects");
460	            }
461	            return;
462	        }
463	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId).stream()
464	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
465	        if (!settled) {
466	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
467	                    "A correction must name the number of a SETTLED claim of the same person");
468	        }
469	    }
470	
471	    /** Refuse a change to a claim dated inside a closed period of the sheet. */
472	    private void refuseIfClosed(String sheetId, LocalDate date) {
473	        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)) {
474	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period");
475	        }
476	    }
477	
478	    /** Refuse a claim dated after its person's retirement date. */
479	    private static void refuseIfRetired(Person person, LocalDate date) {
480	        if (person.refusesClaimOn(date)) {
481	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
482	                    "That claim is dated after " + person.getName() + " retired");
483	        }
484	    }
485	
486	    /** An audit line about a claim; one with a number (a void claim keeps the one it had) ends with it. */
487	    private static String entry(String event, String user, Person person, Claim claim, String number) {
488	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
489	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
490	                + (number == null ? "" : " number=" + number);
491	    }
492	
493	    /** The due on an amount at a rate (a percent): amount × rate / 100, rounded to the cent as the claim it is on
494	     *  rounds (half up rounds a negative half away from zero, as its opposite would). */
495	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal rate, RoundingMode rounding) {
496	        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
497	    }
498	
499	    /** The date that decides how a claim's live figures round: its own date, or for a correction the date of the
500	     *  claim of the same person it corrects. */
501	    public static LocalDate roundingDate(Claim claim, Collection<Claim> sheetClaims) {
502	        if (claim.getCorrects() == null) {
503	            return claim.getDate();
504	        }
505	        return sheetClaims.stream()
506	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
507	                .map(Claim::getDate).findFirst().orElse(claim.getDate());
508	    }
509	
510	    /** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure by the sheet's today: for each
511	     *  full 30 days past the day it is due by, the late percent in force on that boundary date (its due-by plus 30, 60,
512	     *  90 ... days) of the figure, rounded as the claim rounds, added up; 0.00 when not overdue, it has no figure, or
513	     *  it is a correction. */
514	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet) {
515	        BigDecimal none = BigDecimal.ZERO.setScale(2);
516	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(sheet.getToday())) {
517	            return none;
518	        }
519	        return lateChargeAsOpen(claim, figure, sheet);
520	    }
521	
522	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
523	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet) {
524	        BigDecimal none = BigDecimal.ZERO.setScale(2);
525	        if (figure == null || claim.isCorrection()) {
526	            return none;
527	        }
528	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday()) / 30;
529	        RoundingMode rounding = sheet.roundingFor(claim.getDate());
530	        BigDecimal charge = none;
531	        for (long k = 1; k <= periods; k++) {
532	            charge = charge.add(dueOn(figure, sheet.latePctOn(claim.getDueBy().plusDays(30 * k)), rounding));
533	        }
534	        return charge;
535	    }
536	
537	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds, raised to the floor
538	     *  (the one in force on its date) unless it is a correction. */
539	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, BigDecimal floor, RoundingMode rounding) {
540	        BigDecimal due = dueOn(claim.getAmount(), rate, rounding);
541	        return claim.isCorrection() ? due : floored(due, floor);
542	    }
543	
544	    /** A live due raised to the sheet's floor when it is below it. */
545	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
546	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
547	    }
548	
549	    private static BigDecimal scaled(BigDecimal amount) {
550	        return amount.setScale(2, RoundingMode.UNNECESSARY);
551	    }
552	
553	    private static String noteOf(String note) {
554	        return note == null ? "" : note.trim();
555	    }
556	}
