211	            // A viewer's bulk action goes through with nothing done: every selected claim is refused.
212	            return new BulkOpenView(0, (int) request.ids().stream().distinct().count(), List.of());
213	        }
214	        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
215	        int refused = (int) request.ids().stream().distinct().count() - ordered.size();
216	        List<ClaimView> opened = new ArrayList<>();
