240	            return new BulkSettleView(0, (int) request.ids().stream().distinct().count(), List.of());
241	        }
242	        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
243	        int refused = (int) request.ids().stream().distinct().count() - ordered.size();
244	        List<ClaimView> settled = new ArrayList<>();
245	        for (long id : ordered) {
246	            try {
247	                settled.add(ClaimView.of(claims.changeStatus(sheetId, user, id, ClaimStatus.SETTLED)));
248	            } catch (ResponseStatusException refusal) {
249	                refused++;
250	            }
251	        }
252	        return new BulkSettleView(settled.size(), refused, settled);
253	    }
254	}
