export const CLAIM_AMOUNT_PATTERN = /^-?\d+(\.\d{1,2})?$/;

/** An amount ("12.3", "4", "-0.5") in whole cents, so sums are exact. */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
