19	const UNPROVEN = 'This claim\'s due is above the proof threshold, so it needs a proof first.';
20	
21	@Component({
22	  selector: 'app-person-claims',
23	  imports: [ReactiveFormsModule],
24	  template: `
25	    <p>Claimed: <span data-testid="person-claimed">{{ claimed() }}</span></p>
26	
27	    <form [formGroup]="form" (ngSubmit)="submit()"
28	          [attr.aria-label]="(editingId() === null ? 'Add a claim for ' : 'Edit a claim of ') + personName()">
29	      <label [for]="fieldId('amount')">Amount</label>
30	      <input [id]="fieldId('amount')" data-testid="claim-form-amount" formControlName="amount"
31	             inputmode="decimal" autocomplete="off" />
32	      <label [for]="fieldId('date')">Date</label>
33	      <input [id]="fieldId('date')" type="date" data-testid="claim-form-date" formControlName="date" />
34	      <label [for]="fieldId('note')">Note</label>
35	      <input [id]="fieldId('note')" data-testid="claim-form-note" formControlName="note" autocomplete="off" />
36	      <label [for]="fieldId('corrects')">Corrects claim No.</label>
37	      <input [id]="fieldId('corrects')" data-testid="claim-form-corrects" formControlName="corrects"
38	             inputmode="numeric" autocomplete="off" />
39	      <button type="submit" data-testid="claim-form-submit" [disabled]="saving()">
40	        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
41	      </button>
42	      @if (error(); as err) {
43	        <p role="alert" data-testid="claim-form-error">{{ err }}</p>
44	      }
45	    </form>
46	
47	    <ul [attr.aria-label]="'Claims of ' + personName()">
48	      @for (c of claims(); track c.id) {
49	        <li [attr.data-testid]="'claim-row-' + c.id">
50	          <input type="checkbox" data-testid="claim-select" [checked]="selected().has(c.id)"
51	                 (change)="selectToggled.emit({ id: c.id, selected: $any($event.target).checked })"
52	                 [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date" />
53	          No. <span data-testid="claim-number">{{ c.number ?? '' }}</span>
54	          <span data-testid="claim-amount">{{ c.amount }}</span>
55	          on <span data-testid="claim-date">{{ c.date }}</span>
56	          — due <span data-testid="claim-due">{{ dueOf(c) }}</span>
57	          by <span data-testid="claim-due-by">{{ dueByOf(c) }}</span>
58	          — overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span>
59	          in period <span data-testid="claim-period">{{ periodOf(c) }}</span>
60	          <span data-testid="claim-note">{{ c.note }}</span>
61	          corrects No. <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span>
62	          <span data-testid="claim-status">{{ c.status }}</span>
63	          opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span>
64	          — stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span>
65	          — deferred <span data-testid="claim-deferred">{{ deferredOf(c) ? 'yes' : 'no' }}</span>
66	          until <span data-testid="claim-deferred-until">{{ c.deferredUntil ?? '' }}</span>
67	          <label [for]="'claim-defer-date-' + c.id">Defer until</label>
68	          <input [id]="'claim-defer-date-' + c.id" type="date" data-testid="claim-defer-date"
69	                 [value]="deferDates()[c.id] ?? ''" (input)="deferDateChanged(c, $any($event.target).value)" />
70	          <button type="button" data-testid="claim-defer" (click)="defer(c)"
71	                  [attr.aria-label]="'Defer claim of ' + c.amount + ' on ' + c.date">Defer</button>
72	          — proofs <span data-testid="claim-proofs">{{ c.proofs }}</span>
73	          <button type="button" data-testid="claim-proof" (click)="addProof(c)"
74	                  [attr.aria-label]="'Add a proof to claim of ' + c.amount + ' on ' + c.date">Add proof</button>
75	          <button type="button" data-testid="claim-open" (click)="changeStatus(c, 'OPEN')"
76	                  [attr.aria-label]="'Open claim of ' + c.amount + ' on ' + c.date">Open</button>
77	          <button type="button" data-testid="claim-settle" (click)="changeStatus(c, 'SETTLED')"
78	                  [attr.aria-label]="'Settle claim of ' + c.amount + ' on ' + c.date">Settle</button>
79	          <button type="button" data-testid="claim-approve" (click)="approve(c)"
80	                  [attr.aria-label]="'Approve claim of ' + c.amount + ' on ' + c.date">Approve</button>
81	          <button type="button" data-testid="claim-resettle" (click)="resettle(c)"
82	                  [attr.aria-label]="'Re-settle claim of ' + c.amount + ' on ' + c.date">Re-settle</button>
83	          <label [for]="'claim-reject-reason-' + c.id">Reason to reject</label>
84	          <input [id]="'claim-reject-reason-' + c.id" data-testid="claim-reject-reason" autocomplete="off"
85	                 [value]="rejectReasons()[c.id] ?? ''" (input)="reasonChanged(c, $any($event.target).value)" />
86	          <button type="button" data-testid="claim-reject" (click)="reject(c)"
87	                  [attr.aria-label]="'Reject claim of ' + c.amount + ' on ' + c.date">Reject</button>
88	          <button type="button" data-testid="claim-void" (click)="changeStatus(c, 'VOID')"
89	                  [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
90	          <label [for]="'claim-reassign-to-' + c.id">Move to</label>
91	          <select [id]="'claim-reassign-to-' + c.id" data-testid="claim-reassign-to"
92	                  [value]="reassignTo()[c.id] ?? ''" (change)="reassignToChanged(c, $any($event.target).value)">
93	            <option value="">Choose a person</option>
94	            @for (o of others(); track o.id) {
95	              <option [value]="o.id">{{ o.name }}</option>
96	            }
97	          </select>
98	          <button type="button" data-testid="claim-reassign" (click)="reassign(c)"
99	                  [attr.aria-label]="'Move claim of ' + c.amount + ' on ' + c.date + ' to another person'">Move</button>
100	          @if (editingId() === c.id) {
101	            <button type="button" data-testid="claim-cancel" (click)="reset()">Cancel</button>
102	          } @else {
103	            <button type="button" data-testid="claim-edit" (click)="edit(c)"
104	                    [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
105	          }
106	          <ol [attr.aria-label]="'Status log of claim of ' + c.amount + ' on ' + c.date">
107	            @for (l of c.log; track $index) {
108	              <li data-testid="claim-log-line">{{ l.status }} by {{ l.by }} on {{ l.on }} due={{ l.due ?? notAvailable }}</li>
109	            }
110	          </ol>
111	          @if (claimError()?.id === c.id) {
112	            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
113	          }
114	        </li>
115	      }
116	    </ul>
117	  `,
118	})
119	export class PersonClaims {
120	  private readonly sheets = inject(Sheets);
121	  private readonly session = inject(Session);
122	  private readonly api = inject(Claims);
123	
124	  readonly personId = input.required<number>();
125	  readonly personName = input.required<string>();
126	  /** This person's claims, newest first. */
127	  readonly claims = input.required<ClaimView[]>();
128	  /** The rates of each grade, in the order they take effect. */
129	  readonly ratesByGrade = input.required<ReadonlyMap<Grade, readonly RateView[]>>();
130	  /** This person's grades: a claim is at the one in force on its date. */
131	  readonly grades = input.required<Pick<PersonView, 'grade' | 'grades'>>();
132	  /** The sheet's periods, by from-date. */
133	  readonly periods = input.required<readonly PeriodView[]>();
134	  /** The other people on the sheet a claim can be moved to. */
135	  readonly others = input<readonly Pick<PersonView, 'id' | 'name'>[]>([]);
136	  /** The person's holds: their open claims dated within one, and not bound by a statement, count in no total. */
137	  readonly holds = input<readonly HoldView[]>([]);
138	  /** The ids of the claims selected for a bulk action. */
139	  readonly selected = input<ReadonlySet<number>>(new Set());
140	  readonly saved = output<ClaimView>();
141	  readonly selectToggled = output<{ id: number; selected: boolean }>();
142	
143	  protected readonly notAvailable = NOT_AVAILABLE;
144	  protected readonly claimed = computed(() => money(this.claims().filter(countsWithHolds(this.holds(), this.sheets.current()?.today ?? '')).reduce((sum, c) => sum + cents(c.amount), 0)));
145	  protected readonly editingId = signal<number | null>(null);
146	  protected readonly error = signal<string | null>(null);
147	  protected readonly saving = signal(false);
148	  /** The error of the last action taken on a claim's row, until the next action on that row. */
149	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
150	  /** The person chosen to move each claim to, by claim id. */
151	  protected readonly reassignTo = signal<Readonly<Record<number, string>>>({});
152	  /** The date typed to defer each OPEN claim until, by id. */
153	  protected readonly deferDates = signal<Readonly<Record<number, string>>>({});
154	  /** The reason typed to reject each PENDING claim, by id. */
155	  protected readonly rejectReasons = signal<Readonly<Record<number, string>>>({});
156	
157	  protected readonly form = new FormGroup({
158	    amount: new FormControl('', { nonNullable: true }),
159	    date: new FormControl('', { nonNullable: true }),
160	    note: new FormControl('', { nonNullable: true }),
161	    corrects: new FormControl('', { nonNullable: true }),
162	  });
163	
164	  constructor() {
165	    // An error is removed as soon as its form is changed.
166	    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
167	  }
168	
169	  protected dueOf(c: ClaimView): string {
170	    const rates = this.ratesByGrade().get(gradeOn(this.grades(), c.date)) ?? NO_RATES;
171	    const due = claimDueCents(c, rates, this.sheets.current() ?? DEFAULT_DUE_TERMS, roundingDate(c, this.claims()));
172	    return due === null ? NOT_AVAILABLE : money(due);
173	  }
174	
175	  protected dueByOf(c: ClaimView): string {
176	    return c.dueBy;
177	  }
178	
179	  protected overdueOf(c: ClaimView): boolean {
180	    const sheet = this.sheets.current();
181	    return sheet !== null && isOverdue(c, sheet.today);
182	  }
183	
184	  protected deferredOf(c: ClaimView): boolean {
185	    const sheet = this.sheets.current();
186	    return sheet !== null && isDeferred(c, sheet.today);
187	  }
188	
189	  protected deferDateChanged(c: ClaimView, date: string): void {
190	    this.deferDates.update((dates) => ({ ...dates, [c.id]: date }));
191	    if (this.claimError()?.id === c.id) this.claimError.set(null);
192	  }
193	
194	  protected defer(c: ClaimView): void {
195	    this.claimError.set(null);
196	    const sheet = this.sheets.current();
197	    if (!sheet) return;
198	    const until = (this.deferDates()[c.id] ?? '').trim();
199	    if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) {
200	      this.claimError.set({ id: c.id, message: 'Choose the date to defer the claim until.' });
201	      return;
202	    }
203	    this.api.defer(sheet.id, c.id, until).subscribe({
204	      next: (saved) => {
205	        this.deferDates.update((dates) => ({ ...dates, [c.id]: '' }));
206	        this.saved.emit(saved);
207	      },
208	      error: (err: unknown) => this.claimError.set({
209	        id: c.id,
210	        message: err instanceof HttpErrorResponse && err.status === 423
211	          ? 'This claim is dated inside a closed period.'
212	          : err instanceof HttpErrorResponse && err.status === 400
213	            ? `A claim is deferred to a day after today (${sheet.today}).`
214	            : `A ${c.status} claim cannot be deferred; only an OPEN one can.`,
215	      }),
216	    });
217	  }
218	
219	  protected periodOf(c: ClaimView): string {
220	    return periodOn(this.periods(), c.date)?.name ?? '';
221	  }
222	
223	  protected changeStatus(c: ClaimView, status: ClaimStatus): void {
224	    this.claimError.set(null);
225	    const sheet = this.sheets.current();
226	    if (!sheet) return;
227	    this.api.changeStatus(sheet.id, c.id, status).subscribe({
228	      next: (saved) => this.saved.emit(saved),
229	      error: (err: unknown) => this.claimError.set({
230	        id: c.id,
231	        message: err instanceof HttpErrorResponse && err.status === 403
232	          ? status === 'SETTLED' && c.openedBy === this.session.user()
233	            ? 'You opened this claim, so someone else must settle it.'
234	            : `Your role may not ${STATUS_ACTION[status] ?? 'move'} a claim.`
235	          : err instanceof HttpErrorResponse && err.status === 423
236	            ? 'This claim is dated inside a closed period.'
237	            : err instanceof HttpErrorResponse && err.status === 428
238	              ? UNPROVEN
239	            : status === 'SETTLED' && this.deferredOf(c)
240	              ? `This claim is deferred until ${c.deferredUntil}, so it cannot be settled before then.`
241	              : `A ${c.status} claim cannot become ${status}.`,
242	      }),
243	    });
244	  }
245	
246	  protected addProof(c: ClaimView): void {
247	    this.claimError.set(null);
248	    const sheet = this.sheets.current();
249	    if (!sheet) return;
250	    this.api.addProof(sheet.id, c.id).subscribe({
251	      next: (saved) => this.saved.emit(saved),
252	      error: (err: unknown) => this.claimError.set({
253	        id: c.id,
254	        message: err instanceof HttpErrorResponse && err.status === 423
255	          ? 'This claim is dated inside a closed period.'
256	          : `A ${c.status} claim cannot be given a proof.`,
257	      }),
258	    });
259	  }
260	
261	  protected approve(c: ClaimView): void {
262	    this.claimError.set(null);
263	    const sheet = this.sheets.current();
264	    if (!sheet) return;
265	    this.api.approve(sheet.id, c.id).subscribe({
266	      next: (saved) => this.saved.emit(saved),
267	      error: (err: unknown) => this.claimError.set({
268	        id: c.id,
269	        message: err instanceof HttpErrorResponse && err.status === 403
270	          ? c.openedBy === this.session.user()
271	            ? 'You opened this claim, so another steward must approve it.'
272	            : 'Only a steward can approve a claim.'
273	          : this.refusal(err, c, 'approved'),
274	      }),
275	    });
276	  }
277	
278	  protected resettle(c: ClaimView): void {
279	    this.claimError.set(null);
280	    const sheet = this.sheets.current();
281	    if (!sheet) return;
282	    this.api.resettle(sheet.id, c.id).subscribe({
283	      next: (saved) => this.saved.emit(saved),
284	      error: (err: unknown) => this.claimError.set({
285	        id: c.id,
286	        message: err instanceof HttpErrorResponse && err.status === 403
287	          ? 'Only a steward can re-settle a claim.'
288	          : err instanceof HttpErrorResponse && err.status === 423
289	            ? 'This claim is dated inside a closed period.'
290	            : `A ${c.status} claim cannot be re-settled; only a SETTLED one can.`,
291	      }),
292	    });
293	  }
294	
295	  protected reasonChanged(c: ClaimView, reason: string): void {
296	    this.rejectReasons.update((reasons) => ({ ...reasons, [c.id]: reason }));
297	    if (this.claimError()?.id === c.id) this.claimError.set(null);
298	  }
299	
300	  protected reject(c: ClaimView): void {
301	    this.claimError.set(null);
302	    const sheet = this.sheets.current();
303	    if (!sheet) return;
304	    const reason = (this.rejectReasons()[c.id] ?? '').trim().replace(/\s+/g, ' ');
305	    if (reason === '') {
306	      this.claimError.set({ id: c.id, message: 'Type why the claim is rejected.' });
307	      return;
308	    }
309	    this.api.reject(sheet.id, c.id, reason).subscribe({
310	      next: (saved) => {
311	        this.rejectReasons.update((reasons) => ({ ...reasons, [c.id]: '' }));
312	        this.saved.emit(saved);
313	      },
314	      error: (err: unknown) => this.claimError.set({
315	        id: c.id,
316	        message: err instanceof HttpErrorResponse && err.status === 403
317	          ? 'Only a steward can reject a claim.'
318	          : this.refusal(err, c, 'rejected'),
319	      }),
320	    });
321	  }
322	
323	  protected reassignToChanged(c: ClaimView, personId: string): void {
324	    this.reassignTo.update((chosen) => ({ ...chosen, [c.id]: personId }));
325	    if (this.claimError()?.id === c.id) this.claimError.set(null);
326	  }
327	
328	  protected reassign(c: ClaimView): void {
329	    this.claimError.set(null);
330	    const sheet = this.sheets.current();
331	    if (!sheet) return;
332	    const to = Number(this.reassignTo()[c.id] ?? '');
333	    if (!to) {
334	      this.claimError.set({ id: c.id, message: 'Choose the person to move the claim to.' });
335	      return;
336	    }
337	    this.api.reassign(sheet.id, c.id, to).subscribe({
338	      next: (saved) => {
339	        this.reassignTo.update((chosen) => ({ ...chosen, [c.id]: '' }));
340	        this.saved.emit(saved);
341	      },
342	      error: (err: unknown) => this.claimError.set({
343	        id: c.id,
344	        message: err instanceof HttpErrorResponse && err.status === 403
345	          ? 'Your role may not move a claim to another person.'
346	          : err instanceof HttpErrorResponse && err.status === 423
347	            ? 'This claim is dated inside a closed period.'
348	            : err instanceof HttpErrorResponse && err.status === 422
349	              ? 'This claim is dated after that person retired.'
350	              : err instanceof HttpErrorResponse && err.status === 400
351	                ? `That person has no settled claim No. ${c.corrects} for this correction to correct.`
352	                : `A ${c.status} claim cannot be moved; only a DRAFT, OPEN or PENDING one can.`,
353	      }),
354	    });
355	  }
356	
357	  /** Why approving or rejecting a claim was refused, other than by who asked. */
358	  private refusal(err: unknown, c: ClaimView, done: string): string {
359	    return err instanceof HttpErrorResponse && err.status === 423
360	      ? 'This claim is dated inside a closed period.'
361	      : err instanceof HttpErrorResponse && err.status === 428
362	        ? UNPROVEN
363	      : err instanceof HttpErrorResponse && err.status === 400
364	        ? 'Type why the claim is rejected.'
365	        : `A ${c.status} claim cannot be ${done}; only a PENDING one can.`;
366	  }
367	
368	  protected fieldId(field: string): string {
369	    return `claim-form-${field}-${this.personId()}`;
370	  }
371	
372	  protected edit(c: ClaimView): void {
373	    this.claimError.set(null);
374	    // Only a draft can be edited; an open claim is changed by voiding it and adding a new one.
375	    if (c.status !== 'DRAFT') {
376	      this.claimError.set({ id: c.id, message: `A ${c.status} claim cannot be edited. Void it and add a new one.` });
377	      return;
378	    }
379	    this.editingId.set(c.id);
380	    this.form.setValue({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '' },
381	      { emitEvent: false });
382	    this.error.set(null);
383	  }
384	
385	  protected reset(): void {
386	    this.editingId.set(null);
387	    this.form.reset({ amount: '', date: '', note: '', corrects: '' }, { emitEvent: false });
388	    this.error.set(null);
389	  }
390	
391	  protected submit(): void {
392	    // A second submit before the first has answered is ignored, so it stores one record.
393	    if (this.saving()) return;
394	    this.error.set(null);
395	    const sheet = this.sheets.current();
396	    if (!sheet) return;
397	    const value = this.form.getRawValue();
398	    const amount = value.amount.trim();
399	    if (!CLAIM_AMOUNT_PATTERN.test(amount)) {
400	      this.error.set('Type an amount with up to two decimals; a negative one is a correction.');
401	      return;
402	    }
403	    // A negative amount is a correction: it must name the number of a settled claim of this person.
404	    const correction = amount.startsWith('-');
405	    const corrects = value.corrects.trim();
406	    if (correction && !/^\S{1,120}$/.test(corrects)) {
407	      this.error.set('A negative amount is a correction: type the number of the settled claim it corrects.');
408	      return;
409	    }
410	    if (!correction && corrects !== '') {
411	      this.error.set('Only a negative amount (a correction) names a claim it corrects.');
412	      return;
413	    }
414	    const date = value.date.trim();
415	    if (date !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
416	      this.error.set('Choose a date for the claim, or leave it blank for today.');
417	      return;
418	    }
419	    const claim = { amount, date: date === '' ? null : date, note: value.note, corrects: correction ? corrects : null };
420	    const id = this.editingId();
421	    this.saving.set(true);
422	    const request = id === null ? this.api.add(sheet.id, this.personId(), claim) : this.api.update(sheet.id, id, claim);
423	    request.subscribe({
424	      next: (saved) => {
425	        this.saving.set(false);
426	        this.saved.emit(saved);
427	        this.reset();
428	      },
429	      error: (err: unknown) => {
430	        this.saving.set(false);
431	        this.error.set(
432	          err instanceof HttpErrorResponse && err.status === 423
433	            ? 'That claim is dated inside a closed period.'
434	            : err instanceof HttpErrorResponse && err.status === 422
435	              ? 'That claim is dated after the person retired.'
436	            : correction && err instanceof HttpErrorResponse && err.status === 400
437	              ? `Claim No. ${corrects} is not a settled claim of ${this.personName()}, so this cannot correct it.`
438	            : id !== null && err instanceof HttpErrorResponse && err.status === 409
439	              ? 'Only a draft claim can be edited. Void it and add a new one.'
440	              : id === null ? 'Could not add that claim.' : 'Could not save that claim.',
441	        );
442	      },
443	    });
444	  }
445	}
